save(141,dict(paragraphs=["Namita Rani Panda is a poet, short-story writer and translator from Sambalpur, Odisha. Her poetry collections include Blue Butterflies, Rippling Feelings and A Slice of Sky. She has also helped bring other writers together through editorial work, including Radical Rhythm-2 and, with Pradeep Biswal, the anthology Resplendent Rainbow.","Her poems here move between intimate memory and public compassion. In ‘Fragrance’ and ‘Sillage of a Saree’, scent and cloth bring childhood and a mother's presence close again. ‘A Distant Dream’ turns to a child selling flags while longing for a home, while ‘When the Cannons Break the Sky’ asks readers to recognise humanity across the divisions of war. Love appears both as shelter and as a responsibility towards others."],sources=[source('Setu — Namita Rani Panda contributor biography','https://www.setumag.com/2020/04/Author-Namita-Rani-Panda.html',['Sambalpur origin, poet, story writer and translator','Three poetry collections','Radical Rhythm-2 editorial work'],access='search_index_excerpt'),source('Shanta Acharya — anthology bibliography','https://www.shanta-acharya.com/assets/html/shantaAcharya_poetry_anthologies.html',['Resplendent Rainbow edited by Pradeep Biswal and Namita Rani Panda, AuthorsPress 2021']),source('INNSÆI — November 2020 issue','https://www.innsaeijournal.com/wp-content/uploads/2023/05/Innsaei-NOVEMBER-2020-ISSUE.pdf',['Colours of Love and Other Poems title and authorship, 2020'],access='search_index_excerpt')],books=[dict(title='Colours of Love and Other Poems',detail='Poetry collection, 2020. Featured in INNSÆI’s November 2020 issue.',url='https://www.innsaeijournal.com/wp-content/uploads/2023/05/Innsaei-NOVEMBER-2020-ISSUE.pdf'),dict(title='Resplendent Rainbow',detail='Poetry anthology co-edited with Pradeep Biswal. AuthorsPress, 2021.',url='https://www.shanta-acharya.com/assets/html/shantaAcharya_poetry_anthologies.html')],identity_match='Sambalpur origin, same three collection titles and Radical Rhythm editorial credit match captured biography and Setu; anthology contributor confirms co-editor name.',poems_read=[dict(id=120,title='A Distant Dream',basis='Full English original: child selling flags and dreaming of a home.'),dict(id=334,title='Fragrance',basis='Full English original: mangoes, rain, food/prasad, beloved and child through scent.'),dict(id=669,title='Sillage of a Saree',basis='Full English original: mother’s sari and remembered maternal presence.'),dict(id=695,title='Under the Umbrella of Your Love',basis='Full English original: shelter, altered weather, flowers, river and flute.'),dict(id=747,title='When the Cannons Break the Sky',basis='Full English original: war, grieving mothers, soldier sparing child, mercy across uniforms.')],limitations=['Dated school appointment not asserted as current.','Captured Namitarani heading preserved; public sources space name as Namita Rani.','INNSÆI direct fetch failed; book entry supported by indexed journal text, not a claimed full PDF inspection.','Other captured books and translation credits retained in source but not expanded without corroboration.','Mother/child imagery discussed as poetry, not independently established personal history.'],research_leads=[dict(url='https://www.ibpbooks.com/colours-of-love-and-other-poems/p/49670',access='search_index_excerpt; direct fetch error',finding='Retailer corroborates author and collection; no price or availability claim.')],next_action='Independent author/editor review; confirm preferred spacing and complete bibliography.'))
